// Open Autonomy's Discord setup (packages/kit-hermes/src/setup.ts:313-345 at 0841076): fetch with the saved bot token,
// the application read and the home channel checked, then the home channel's report posted as a scheduled job does.
import assert from 'node:assert/strict';
import { readFileSync, writeFileSync } from 'node:fs';
if (!process.env.VOLTER_WORLD) throw new Error('Run this app through its World.');
const token = process.env.DISCORD_BOT_TOKEN;
const api = async (path, init = {}) => {
  const response = await fetch(`https://discord.com/api/v10/${path}`, { signal: AbortSignal.timeout(30_000), ...init, headers: { Authorization: `Bot ${token}`, ...(init.body ? { 'content-type': 'application/json' } : {}), ...init.headers } });
  if (!response.ok) throw new Error(`Discord ${path} returned ${response.status}: ${await response.text()}`);
  return response.json();
};
const receiptFile = 'channels.json';

if (process.argv[2] === 'readback') {
  const saved = JSON.parse(readFileSync(receiptFile, 'utf8'));
  const me = await api('oauth2/applications/@me');
  assert.equal(me.id, saved.application);
  const destination = await api(`channels/${saved.channel}`);
  assert.equal(destination.guild_id, saved.guild);
  const messages = await api(`channels/${saved.channel}/messages`);
  const report = messages.find((m) => m.id === saved.message);
  assert.ok(report, 'the report is no longer in the home channel');
  assert.equal(report.content, saved.content);
  assert.equal(report.author.id, me.bot.id);
  console.log(JSON.stringify({ retained: true, application: me.id, channel: destination.id, message: report.id }));
} else {
  // The project's owner has a Discord account and a server, and adds the project's bot to it from the install link.
  const twin = (path, body) => fetch(`${process.env.DISCORD_TWIN_URL}/_twin/${path}`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(body) });
  const password = `oa-${process.env.DISCORD_CLIENT_ID}-owner`;
  const owner = await twin('people', { username: 'aaron', global_name: 'Aaron Ng', email: 'aaron@open-autonomy.example', password });
  assert.equal(owner.status, 201, await owner.clone().text());
  const server = await (await twin('guilds', { owner: 'aaron', name: 'Open Autonomy' })).json();
  assert.ok(server.id && server.system_channel_id, JSON.stringify(server));
  const install = (extra) => fetch('https://discord.com/oauth2/authorize', { method: 'POST', headers: { 'content-type': 'application/x-www-form-urlencoded' }, body: new URLSearchParams({ client_id: process.env.DISCORD_CLIENT_ID, scope: 'bot', permissions: '8', username: 'aaron', password, ...extra }) });
  const added = await install({ decision: 'authorize', guild_id: server.id });
  assert.equal(added.status, 200);
  assert.match(await added.text(), /was added to Open Autonomy/);
  const channel = process.env.DISCORD_HOME_CHANNEL || server.system_channel_id;

  // stepDiscord: the application and the agreed destination
  const me = await api('oauth2/applications/@me');
  assert.ok(typeof me.id === 'string' && /^\d+$/.test(me.id));
  assert.equal(me.id, process.env.DISCORD_CLIENT_ID);
  const destination = await api(`channels/${channel}`);
  assert.equal(destination.id, channel);
  assert.equal(destination.guild_id, server.id);

  // a scheduled job's report to the home channel
  const content = 'Weekly report: 3 pull requests merged, 1 release cut.';
  const posted = await api(`channels/${channel}/messages`, { method: 'POST', body: JSON.stringify({ content }) });
  assert.equal(posted.content, content);
  assert.equal(posted.channel_id, channel);
  assert.equal(posted.author.id, me.bot.id);
  writeFileSync(receiptFile, JSON.stringify({ application: me.id, guild: server.id, channel, message: posted.id, content }) + '\n');
  console.log(JSON.stringify({ application: me.id, name: me.name, guild: server.id, channel, message: posted.id }));
}
